pragma solidity 0.8.23;

library FeeLogic {
    uint256 internal constant PERCENTAGE_FACTOR = 1e4;

    function calculateFeePerTaker(
        uint256 _amount,
        uint256 _ratio,
        uint256 _takers
    ) internal pure returns (uint256) {
        if (_ratio <= 0 || _takers == 0 || _amount == 0) return 0;

        uint256 total = _amount * _ratio;
        uint256 per_taker = total / _takers;

        return per_taker / PERCENTAGE_FACTOR;
    }

    function clampFee(uint24 _value) internal pure returns (uint24) {
        if (_value < 0) return uint24(0);
        if (_value > 10000) return uint24(10000);

        return _value;
    }
}
