pragma solidity 0.8.23;

import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {IVault} from "../../interfaces/IVault.sol";

import {Signature, Transaction, VaultParameters} from "../../libraries/Data.sol";

import {VaultLogic} from "../../libraries/logic/VaultLogic.sol";
import {FeeLogic} from "../../libraries/logic/FeeLogic.sol";

contract Vault is IVault, ReentrancyGuard {
    address private pool;
    address[] private owners;
    mapping(address => bool) private mOwners;

    mapping(uint256 => mapping(address => bool)) private txSignatures;

    // Holds balance of assets.
    // Address is either ERC20 address or Zero Address for native.
    mapping(address => uint256) private balance;

    // Holds balance of assets of account.
    // Address is either ERC20 address or Zero Address for native.
    mapping(address => mapping(address => uint256)) private balanceOf;

    uint256 private threshold;

    mapping(uint256 => Transaction) private transactions;

    error AlreadyExecuted();
    error AlreadySet();
    error AlreadySigned();
    error NotEnoughSignatures();
    error NotOwner();
    error NotPool();

    modifier onlyOwners() {
        if (!_isOwner(msg.sender)) revert NotOwner();
        _;
    }

    modifier onlyPool() {
        if (!_isPool(msg.sender)) revert NotPool();
        _;
    }

    constructor(VaultParameters memory _parameters) {
        _setPool(msg.sender);
        _setOwners(_parameters);
    }

    // -----------------------------------------------------------------
    // External API
    // -----------------------------------------------------------------

    /// @notice Fallback function to receive native.
    receive() external payable virtual {}

    function depositNative(address _address) external payable onlyPool {
        Address.sendValue(payable(address(this)), msg.value);

        _adjustBalance(_address, address(0), msg.value);

        emit Deposited(_address, address(0), msg.value);
    }

    function depositERC20WithPermit(
        address _token,
        address _from,
        uint256 _value,
        uint256 _deadline,
        uint8 _permitV,
        bytes32 _permitR,
        bytes32 _permitS
    ) external onlyPool {
        try
            IERC20Permit(_token).permit(
                _from,
                address(this),
                _value,
                _deadline,
                _permitV,
                _permitR,
                _permitS
            )
        {} catch {}

        _depositERC20(_token, _from, _value);
    }

    function depositERC20(
        address _token,
        address _from,
        uint256 _value
    ) external onlyPool {
        _depositERC20(_token, _from, _value);
    }

    function getNativeBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getNativeBalanceOf(
        address _address
    ) external view returns (uint256) {
        return balanceOf[address(0)][_address];
    }

    function getERC20Balance(address _token) external view returns (uint256) {
        return balance[_token];
    }

    function getERC20BalanceOf(
        address _token,
        address _address
    ) external view returns (uint256) {
        return balanceOf[_token][_address];
    }

    /// @notice Checks if an address is an owner of the vault.
    /// @param _address The address to check.
    /// @return True if the address is an owner, false otherwise.
    function isOwner(address _address) external view returns (bool) {
        return _isOwner(_address);
    }

    /// @notice Retrieves the list of owner addresses.
    /// @return An array of owner addresses.
    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    /// @notice Retrieves the transaction threshold.
    /// @return The number of signatures required to execute a transaction.
    function getThreshold() external view returns (uint256) {
        return threshold;
    }

    /// @notice Retrieves a transaction.
    /// @return The Transaction struct.
    function getTX(uint256 _index) external view returns (Transaction memory) {
        return _getTX(_index);
    }

    /// @notice Submits a new transaction to the vault.
    /// @param _token ERC20 token address (use address(0) for native).
    /// @param _to Recipient address.
    /// @param _value Amount of tokens or native to transfer.
    function submitTX(
        uint256 _id,
        address _token,
        address _to,
        uint256 _value,
        address _submitter
    ) external onlyPool {
        return _submitTX(_id, _token, _to, _value, _submitter);
    }

    /// @notice Signs an existing transaction.
    /// @param _id The index of the transaction to sign.
    /// @param _signer The address of the signing owner.
    function signTX(uint256 _id, address _signer) external onlyPool {
        return _signTX(_id, _signer);
    }

    /// @notice Executes a signed transaction. Only callable by the deploying Pool.
    /// @param _id The index of the transaction to execute.
    /// @param _executor The address of the executing owner.
    function executeTX(
        uint256 _id,
        address _executor,
        uint24 _feeRatio,
        address[] memory _feeTakers
    ) external onlyPool {
        return _executeTX(_id, _executor, _feeRatio, _feeTakers);
    }

    /// @notice Checks if a transaction is ready for execution.
    /// @param _id The index of the transaction to check.
    /// @return True if the transaction can be executed, false otherwise.
    function isTXExecutable(uint256 _id) external view returns (bool) {
        return _isTXExecutable(_id);
    }

    function hasSigned(
        uint256 _id,
        address _address
    ) external view returns (bool) {
        return txSignatures[_id][_address];
    }

    // -----------------------------------------------------------------
    // Internal API
    // -----------------------------------------------------------------

    function _depositERC20(
        address _token,
        address _from,
        uint256 _value
    ) internal {
        SafeERC20.safeTransferFrom(
            IERC20(_token),
            _from,
            address(this),
            _value
        );

        _adjustBalance(_from, _token, _value);

        emit Deposited(_from, _token, _value);
    }

    /// @dev Retrieves a transaction by index.
    /// @param _index The index of the transaction.
    /// @return The transaction struct (ref. to storage).
    function _getTX(
        uint256 _index
    ) internal view returns (Transaction storage) {
        return transactions[_index];
    }

    function _createTx(
        uint256 _id,
        address _token,
        address _to,
        uint256 _value
    ) internal {
        // assign new transaction to the storage location
        Transaction storage transaction = transactions[_id];

        transaction.id = _id;
        transaction.token = _token;
        transaction.to = _to;
        transaction.value = _value;
        transaction.signatureCount = 0;
    }

    /// @dev Internal function to submit a new transaction.
    function _submitTX(
        uint256 _id,
        address _token,
        address _to,
        uint256 _value,
        address _submitter
    ) internal {
        _createTx(_id, _token, _to, _value);

        emit TXSubmitted(_id, _submitter, transactions[_id]);
    }

    /// @dev Internal function to sign a transaction.
    function _signTX(uint256 _id, address _signer) internal {
        if (mOwners[_signer] != true) revert NotOwner();
        if (txSignatures[_id][_signer] == true) revert AlreadySigned();

        Transaction storage transaction = _getTX(_id);

        if (transaction.signatureCount >= threshold) revert AlreadySigned();

        transaction.signatureCount += 1;
        transaction.signatures.push(Signature({by: _signer}));
        txSignatures[_id][_signer] = true;

        emit TXSigned(transaction.id, _signer, transaction);
    }

    /// @dev Internal function to execute a transaction.
    function _executeTX(
        uint256 _index,
        address _executor,
        uint24 _feeRatio,
        address[] memory _feeTakers
    ) internal {
        if (mOwners[_executor] != true) revert NotOwner();
        Transaction storage transaction = _getTX(_index);

        if (transaction.signatureCount < threshold)
            revert NotEnoughSignatures();

        if (transaction.executed) revert AlreadyExecuted();

        transaction.executed = true;

        uint256 count = _feeTakers.length;

        uint256 fee = FeeLogic.calculateFeePerTaker(
            transaction.value,
            _feeRatio,
            count
        );

        if (transaction.token == address(0)) {
            _executeNative(transaction.to, transaction.value);

            if (fee > 0) {
                for (uint256 i; i < count; i++) {
                    _executeNative(_feeTakers[i], fee);
                }
            }
        } else {
            _executeERC20(transaction.token, transaction.to, transaction.value);

            if (fee > 0) {
                for (uint256 i; i < count; i++) {
                    _executeERC20(transaction.token, _feeTakers[i], fee);
                }
            }
        }

        emit TXExecuted(transaction.id, _executor, transaction);
    }

    /// @dev Internal function to execute a native transfer.
    function _executeNative(address _to, uint256 _value) internal nonReentrant {
        Address.sendValue(payable(_to), _value);
    }

    /// @dev Internal function to execute an ERC20 token transfer.
    function _executeERC20(
        address _token,
        address _to,
        uint256 _value
    ) internal nonReentrant {
        SafeERC20.safeTransfer(IERC20(_token), _to, _value);
    }

    /// @dev Internal function to check if a transaction is executable.
    function _isTXExecutable(uint256 _index) internal view returns (bool) {
        Transaction storage transaction = _getTX(_index);

        return !transaction.executed && transaction.signatureCount == threshold;
    }

    function _adjustBalance(
        address _address,
        address _token,
        uint256 _value
    ) internal nonReentrant {
        balance[_token] += _value;
        balanceOf[_token][_address] += _value;
    }

    function _isOwner(address _address) internal view returns (bool) {
        return mOwners[_address];
    }

    /// @dev Internal function to set the initial owners and threshold.
    //       It will revert if owners are already set.
    function _setOwners(VaultParameters memory _parameters) internal {
        if (owners.length > 0) revert AlreadySet();

        VaultLogic.checkThreshold(_parameters);

        owners = _parameters.owners;
        threshold = _parameters.threshold;

        uint256 length = owners.length;
        unchecked {
            for (uint256 i = 0; i < length; i++) {
                mOwners[owners[i]] = true;
            }
        }
    }

    /// @dev Internal function to check if the address belongs to the deploying pool
    function _isPool(address _address) internal view returns (bool) {
        return _address == pool;
    }

    /// @dev Internal function to set the pool. Will revert if already set.
    function _setPool(address _pool) internal {
        if (pool != address(0)) revert AlreadySet();

        pool = _pool;
    }

    // -----------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------

    event Deposited(
        address indexed depositor,
        address indexed token,
        uint256 value
    );

    event TXSubmitted(
        uint256 indexed index,
        address indexed submitter,
        Transaction transaction
    );

    event TXSigned(
        uint256 indexed index,
        address indexed signer,
        Transaction transaction
    );

    event TXExecuted(
        uint256 indexed index,
        address indexed executor,
        Transaction transaction
    );
}
